def run(program):
    stack = []
    output = []
    pc = 0
    while pc < len(program):
        op, *args = program[pc]
        pc += 1
        if op == "PUSH":
            stack.append(args[0])
        elif op == "ADD":
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif op == "SUB":
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif op == "MUL":
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif op == "DUP":
            stack.append(stack[-1])
        elif op == "PRINT":
            output.append(stack.pop())
        elif op == "JUMPZ":
            if stack.pop() == 0:
                pc = args[0]
        elif op == "JUMP":
            pc = args[0]
    return output

