    check_eq(run([("PUSH", 2), ("PUSH", 3), ("ADD",), ("PUSH", 4), ("MUL",), ("PRINT",)]), [20])
    check_eq(run([("PUSH", 10), ("PUSH", 3), ("SUB",), ("PRINT",)]), [7])

@test("several prints and DUP")
def _():
    check_eq(run([("PUSH", 5), ("DUP",), ("PRINT",), ("PUSH", 1), ("ADD",), ("PRINT",)]), [5, 6])
    check_eq(run([]), [])

@test("a countdown loop")
def _():
    program = [
        ("PUSH", 3),        # 0
        ("DUP",),           # 1  loop: keep a copy to print
        ("PRINT",),         # 2
        ("PUSH", 1),        # 3
        ("SUB",),           # 4
        ("DUP",),           # 5
        ("JUMPZ", 8),       # 6  stop at zero
        ("JUMP", 1),        # 7
    ]
    check_eq(run(program), [3, 2, 1])

